'use strict';
(()=>{
 const M=window.MACHI_OPPORTUNITY,$=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const records={}; let city='',property=null,demo=false;
 const el=document.createElement('section');el.id='community';el.className='section';$('#sources').before(el);
 const fixture='活動：空き家の手入れを相談する模擬活動\n窓口：デモ窓口（実在しません）\n対象：未確認\n日程：未確認\n費用：未確認\n連絡先：未確認\nDIY許可：未確認\n通信・仕事：未確認\n移動：未確認';
 const question='現在相談を受け付けていますか。対象者、日程、費用、受け入れを決める方、短期滞在の条件を教えてください。DIYは所有者同意・作業範囲・指導体制を、仕事は通信と作業場所を、移動は実際の便・最終区間・帰路を確認したいです。';
 function contact(){const r=records[city];return `まちホリ！ v0.2.1 — 未送信の問い合わせ文案\n地域：${city}\n${property?'参考の匿名化物件ID：'+property+'（活動との関係は未確認）\n':''}滞在希望：${$('#duration').selectedOptions[0].textContent}\n移動希望：${$('#transport').selectedOptions[0].textContent}\n関心：${[...document.querySelectorAll('input[name="interest"]:checked')].map(x=>x.value).join('、')||'未選択'}\n${demo&&M.visible(r,city)?'デモ活動を参考にした練習用です。実在の募集・宛先ではありません。\n':''}\n${question}\n\n送信前に、実在の公式窓口・宛先と文面を本人が確認してください。個人情報は含めていません。参加確約・予約ではありません。`;}
 function render(){
  const r=records[city],s=r?M.status(r):null;
  el.innerHTML=`<div class="section-heading"><div><p class="eyebrow">LAYER B / COMMUNITY ACCESS · v0.2.1</p><h2>迎える人と、関われることを確かめる。</h2></div><a href="#discover">地域を選び直す ↑</a></div><p>層Aは住宅・交通の実データ、層Bは地域側が確認する参加機会です。5市はデモ用の抽出範囲で、元データ全体の対象地域数ではありません。</p><p id="community-context" class="notice">${city?esc(city)+(property?' / 参考物件 '+esc(property):''):'先に地域を絞るか、物件を選んでください。'}。同じ市でも、活動と物件の提携・宿泊利用を示しません。</p><div class="panel"><h3>実在の参加機会：未登録</h3><p>受け入れ可否は不明です。窓口・参加条件・現在のDIY許可・実績は確認されていません。再訪・共同活動の実績も未登録で、ゼロという意味ではありません。募集意思はあなたの参加確約ではありません。</p></div>
  ${city?`<div class="panel" style="margin-top:20px"><h3>希望と確認事項を、問い合わせ文案にする</h3><p>実在の宛先は未確認です。自動送信・予約はありません。氏名・連絡先等を入力しないでください。</p><button class="button secondary" id="make-contact">現在の希望で文案を作成</button><label class="review-field" for="contact-draft">本人確認用の文案</label><textarea id="contact-draft" rows="10" readonly></textarea><button class="button secondary" id="save-contact" disabled>文案を端末に保存</button></div>`:''}
  <details id="demo-review" ${demo?'open':''}><summary>確認フローを試す（架空データ・この画面内だけ）</summary><p class="notice">これは管理画面ではありません。誰でも試せる確認手順のデモです。操作は端末内のメモリだけに反映され、再読み込みで消えます。実在の募集・個人情報を入力しないでください。AIや外部サイトには接続せず、定型行を読み取る簡易処理です。</p>
  ${city?`<button class="button secondary" id="load-example">${r?'模擬資料をリセット':'模擬資料を読み込む'}</button>${r?`<div class="detail-grid"><div class="panel"><h3>1. 既存ページの原文を確認する練習</h3><label class="review-field" for="review-source">出典URL（架空・リンクしません）</label><input id="review-source" value="${esc(r.source)}" maxlength="500"><label class="review-field" for="review-text">模擬原文（項目名：内容）</label><textarea id="review-text" rows="11" maxlength="4000">${esc(r.text)}</textarea><p>原文を修正して再作成すると、以前の確認と閲覧用反映は解除されます。出典更新日：不明 / 取得日：${esc(r.retrieved)} / 公開主体：${esc(r.owner)}</p><button class="button secondary" id="extract-draft">定型行から下書きを再作成</button></div><div class="panel"><h3>2. 原文と下書きを照合する</h3><span class="status-label" id="review-state">${esc(M.labels[s])}</span><dl class="data-table">${Object.entries(M.fields).map(([key,label])=>`<div><dt>${label}</dt><dd>${esc(r.values[key]||'未確認')}<small class="evidence-line">原文：${esc(r.evidence[key]||'記載なし')}</small></dd></div>`).join('')}</dl><p>確認者：${esc(r.reviewer||'未確認')} / 確認日：${esc(r.reviewed||'未確認')}<br>これは模擬資料です。利用条件の実査・権限の認証は行いません。</p><label class="review-field" for="review-expiry">再確認期限（最大30日・UTC日付）</label><input type="date" id="review-expiry" value="${esc(r.expires)}" ${s==='awaiting_confirmation'?'':'disabled'}>${[['authority','担当者の確認権限を確認する練習'],['reuse','出典と再利用条件を確認する練習'],['privacy','個人情報を含まないことを確認する練習']].map(([key,label])=>`<label class="check-row"><input type="checkbox" data-gate="${key}" ${r.gates[key]?'checked':''} ${s==='awaiting_confirmation'?'':'disabled'}>${label}</label>`).join('')}<div class="plan-actions">${['draft','needs_reconfirmation','withdrawn','rejected'].includes(s)?'<button class="button secondary" data-action="request">確認待ちにする</button>':''}${s==='awaiting_confirmation'?'<button class="button primary" data-action="confirm">人の確認を記録（デモ）</button><button class="button secondary" data-action="reject">却下</button>':''}${s==='confirmed'?'<button class="button primary" data-action="publish">閲覧用デモに反映</button>':''}${['confirmed','published'].includes(s)?'<button class="button secondary" data-action="invalidate">重要変更・再確認が必要</button><button class="button secondary" id="expire-example">期限切れを試す</button>':''}${!['withdrawn','rejected'].includes(s)?'<button class="button secondary" data-action="withdraw">取り下げ</button>':''}</div><p id="review-feedback" role="status"></p><details><summary>この画面内の操作履歴</summary><ul>${r.history.map(h=>`<li>${esc(h.date)} ${esc(h.action)}</li>`).join('')}</ul></details></div></div><div class="panel" style="margin-top:20px"><h3>3. 閲覧用デモ（実在の参加機会ではありません）</h3>${M.visible(r,city)?`<p id="demo-opportunity"><strong>${esc(r.values.activity)}</strong><br>${esc(r.values.host||'窓口未確認')} / ${esc(city)}<br>確認日 ${esc(r.reviewed)} / 期限 ${esc(r.expires)}</p><p>対象・日程・費用・DIY許可は上記の原文と照合してください。未確認の条件は確認が必要です。移動とコミュニティ受け入れは別々に確認し、仕事・滞在も相談します。体験談・再訪・共同活動の実績は未登録です。</p>`:'<p id="demo-empty">表示できるデモ活動はありません。下書き・確認待ち・期限切れ・取り下げは表示対象外です。人の確認後に別途「閲覧用デモに反映」が必要です。</p>'}</div>`:''}`:'<p>地域を選ぶと、その地域に限定したデモを試せます。</p>'}</details>`;
  $('#demo-review').addEventListener('toggle',e=>demo=e.target.open);
  if(!city)return;
  $('#make-contact').onclick=()=>{$('#contact-draft').value=contact();$('#save-contact').disabled=false;};
  $('#save-contact').onclick=()=>{const b=new Blob(['\ufeff'+$('#contact-draft').value],{type:'text/plain;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='まちホリ_v0.2.1_未送信文案.txt';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
  $('#load-example').onclick=()=>{demo=true;records[city]=M.draft(city,fixture,'https://example.invalid/machiholi-demo');render();};
  if(!r)return;
  $('#extract-draft').onclick=()=>{records[city]=M.draft(city,$('#review-text').value,$('#review-source').value);render();};
  el.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{const input={...r,gates:{...r.gates}};if(s==='awaiting_confirmation'){input.expires=$('#review-expiry').value;el.querySelectorAll('[data-gate]').forEach(c=>input.gates[c.dataset.gate]=c.checked);}records[city]=M.transition(input,b.dataset.action);render();}catch(e){$('#review-feedback').textContent=e.message;}});
  const expire=$('#expire-example');if(expire)expire.onclick=()=>{records[city]={...r,expires:M.addDays(M.today(),-1)};render();};
 }
 document.addEventListener('machiholi:place',e=>{city=e.detail.city;property=e.detail.id;render();});
 $('#preferences').addEventListener('change',e=>{if(e.target.id==='region'){city=e.target.value.split(' ').slice(1).join(' ');property=null;}render();});
 // Re-evaluate expiry on tab return; never persist personal inputs or demo reviews.
 document.addEventListener('visibilitychange',()=>{if(!document.hidden)render();});
 setInterval(()=>{const r=records[city];if(r&&['confirmed','published'].includes(r.status)&&M.status(r)==='needs_reconfirmation'){r.status='needs_reconfirmation';render();}},60000);
 render();
})();
